CREATE TYPE "tipo_categoria" AS ENUM (
  'gasto',
  'receita'
);

CREATE TABLE "usuarios" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(100) NOT NULL,
  "email" varchar(150) UNIQUE NOT NULL,
  "senha_hash" varchar(255) NOT NULL,
  "criado_em" timestamp DEFAULT (now())
);

CREATE TABLE "categorias" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" int,
  "nome" varchar(60) NOT NULL,
  "tipo" tipo_categoria NOT NULL
);

CREATE TABLE "saldos" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" int UNIQUE NOT NULL,
  "valor_atual" decimal(12,2) NOT NULL DEFAULT 0,
  "atualizado_em" timestamp DEFAULT (now())
);

CREATE TABLE "gastos" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" int NOT NULL,
  "categoria_id" int,
  "valor" decimal(12,2) NOT NULL,
  "descricao" varchar(255),
  "data_gasto" date NOT NULL,
  "criado_em" timestamp DEFAULT (now())
);

CREATE TABLE "receitas" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" int NOT NULL,
  "categoria_id" int,
  "valor" decimal(12,2) NOT NULL,
  "descricao" varchar(255),
  "data_receita" date NOT NULL,
  "criado_em" timestamp DEFAULT (now())
);

CREATE TABLE "orcamentos" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" int NOT NULL,
  "mes" int NOT NULL,
  "ano" int NOT NULL,
  "limite_geral" decimal(12,2) NOT NULL,
  "valor_disponivel" decimal(12,2) NOT NULL
);

CREATE TABLE "retiradas" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" int NOT NULL,
  "valor" decimal(12,2) NOT NULL,
  "descricao" varchar(255),
  "data_retirada" date NOT NULL,
  "criado_em" timestamp DEFAULT (now())
);

CREATE TABLE "relatorios" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" int NOT NULL,
  "titulo" varchar(120) NOT NULL,
  "tipo" varchar(50) NOT NULL,
  "periodo_inicio" date NOT NULL,
  "periodo_fim" date NOT NULL,
  "dados" json,
  "gerado_em" timestamp DEFAULT (now())
);

CREATE INDEX ON "gastos" ("usuario_id", "data_gasto");

CREATE INDEX ON "receitas" ("usuario_id", "data_receita");

CREATE UNIQUE INDEX ON "orcamentos" ("usuario_id", "mes", "ano");

COMMENT ON COLUMN "categorias"."usuario_id" IS 'null = categoria padrão do sistema';

COMMENT ON COLUMN "orcamentos"."mes" IS '1 a 12';

COMMENT ON COLUMN "relatorios"."tipo" IS 'ex: grafico_gastos';

COMMENT ON COLUMN "relatorios"."dados" IS 'dados do gráfico já calculados';

ALTER TABLE "categorias" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "saldos" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "gastos" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "gastos" ADD FOREIGN KEY ("categoria_id") REFERENCES "categorias" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "receitas" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "receitas" ADD FOREIGN KEY ("categoria_id") REFERENCES "categorias" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "orcamentos" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "retiradas" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "relatorios" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;
